{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"// preinscription
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil; 
import org.joget.apps.app.service.*;
import org.joget.apps.form.model.*;
import org.joget.apps.form.service.*;
import org.joget.apps.form.model.FormData;
import java.sql.*;
import java.util.*;
import org.joget.commons.util.LogUtil;
import org.json.JSONObject;
import java.net.HttpURLConnection;
import java.net.URL;
import java.io.OutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import org.json.JSONArray;
import org.json.JSONObject;
import org.joget.apps.app.model.AppDefinition;
import org.joget.apps.app.service.AppService;
import org.joget.workflow.model.WorkflowAssignment;
String file_name = "Récépissé.docx";
String file_name2 = "Récépissé.pdf";
String table_name = "d_preinscription";
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
String recordID = appService.getOriginProcessId(workflowAssignment.getProcessId());
LogUtil.info("--------------",recordID);
String template = "/home/wuri/Projects/apidocx/templates/temp_preins_rsu.docx";
String generation_path = "#appVariable.gen_path#";
public String getJson() {
Connection con = null;
String result = "";
try {
 DataSource ds = (DataSource)AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 if (!con.isClosed()) {
 LogUtil.info("1=================","connection verified");
 PreparedStatement stmt = con.prepareStatement("SELECT c_nom, c_prenom,app_fd_d_preinscription.dateCreated, c_departement, c_arrondissement, c_concession, c_role_menage, c_nom_cm, c_prenom_cm,c_commune,c_village_quartier_ville, c_adresse , c_id_demande ,dep.c_libelle as dep ,arr.c_libelle as arr,comm.c_libelle as comm FROM app_fd_d_preinscription left join app_fd_department dep on( dep.id=app_fd_d_preinscription.c_departement ) left join app_fd_arrondissement arr on (arr.id=app_fd_d_preinscription.c_arrondissement) left join app_fd_commune comm on (comm.id=app_fd_d_preinscription.c_commune) WHERE app_fd_d_preinscription.id=?;");
 stmt.setString(1, recordID);
 LogUtil.info("1.2=================","query not-executed");
 
 ResultSet rs = stmt.executeQuery();
 LogUtil.info("2=================","query executed");

 JSONObject jsonObject = new JSONObject();
 try {
 if (rs.next()) {
 jsonObject.put("Nom", rs.getString("c_nom"));
 jsonObject.put("Prenom", rs.getString("c_prenom"));
 // jsonObject.put("Date", rs.getString("dateCreated"));
 jsonObject.put("Date"," #date.dd-MM-yyyy#");
 jsonObject.put("Departement", rs.getString("dep"));
 jsonObject.put("Arrondissement", rs.getString("arr"));
 jsonObject.put("Concession", rs.getString("c_concession"));
 LogUtil.info("role menage----",rs.getString("c_role_menage"));
 if(rs.getString("c_role_menage").equals("membre")){
 jsonObject.put("Nom_CM", rs.getString("c_nom_cm"));
 jsonObject.put("Prenom_CM", rs.getString("c_prenom_cm"));
 }else{
 jsonObject.put("Nom_CM", rs.getString("c_nom"));
 jsonObject.put("Prenom_CM", rs.getString("c_prenom"));
 }
 
 jsonObject.put("Commune", rs.getString("comm"));
 jsonObject.put("Village", rs.getString("c_village_quartier_ville"));
 LogUtil.info("adresse----",rs.getString("c_adresse"));
 jsonObject.put("Addresse_Complete", rs.getString("c_adresse"));
 jsonObject.put("ID_Demande",rs.getString("c_id_demande"));
 }
 LogUtil.info("2=================",jsonObject.toString());

 } catch (Exception e) {
 LogUtil.error("erreur",e," ");
 }
 JSONObject final_json = new JSONObject();
 try{
 final_json.put("data",jsonObject);
 final_json.put("output_file_name",file_name);
 final_json.put("output_path",generation_path+table_name+"/"+recordID);
 final_json.put("source_path",template);
 }catch(Exception e) {
 // Handle exceptions
 LogUtil.error("erreur",e," ");
 
 }
 result=final_json.toString();
 }
} catch(Exception ex) {
 LogUtil.error("erreur",ex," ");
} finally {
 try {
 if(con != null)
 con.close();
 } catch(SQLException e) {}
}

return result;
}
//-----------------------LOAD DATA INTO FIELDS------------------------------------------------------------
String json_field = getJson();
LogUtil.info("fichier final", json_field);
//------------------API CALL AND RESPONSE RETRIEVAL-----------------------------------------------------------------

String apiUrl = "#appVariable.api_gen_url#";
try {
// Create URL object
URL url = new URL(apiUrl);

// Open connection
HttpURLConnection connection = (HttpURLConnection) url.openConnection();

// Set the request method to POST
connection.setRequestMethod("POST");

// Set Content-Type header to application/json
connection.setRequestProperty("Content-Type", "application/json");

// Enable output and input streams
connection.setDoOutput(true);
connection.setDoInput(true);

// Get output stream
OutputStream os = connection.getOutputStream();
os.write(json_field.getBytes());
os.flush();
os.close();

// Get response code
int responseCode = connection.getResponseCode();

// Read response
BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
String inputLine;
StringBuffer response = new StringBuffer();

while ((inputLine = in.readLine()) != null) {
 response.append(inputLine);
}
in.close();

// Print response
LogUtil.warn("--------------------------------------------->",response.toString());
//---------------------------------- Update DB if file generated ----------------------------------------
if (responseCode == 200) {
 Connection con = null;
 try {
 LogUtil.warn("------------------------------>Response Code : " , responseCode.toString());
 
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 if (con != null && !con.isClosed()) {
 LogUtil.warn("------------------------------>Connection Open","<--------------------");
 String updateQuery = "UPDATE app_fd_d_preinscription SET c_recepisse = ? WHERE id = ?";
 PreparedStatement updateStatement = con.prepareStatement(updateQuery);
 updateStatement.setString(1, file_name2);
 updateStatement.setString(2, recordID);
 updateStatement.executeUpdate();
 LogUtil.warn("------------------------------>Record updated successfully","<-------------");
 }
 } catch (Exception ex) {
 LogUtil.error("Error: ", ex,"------");
 } finally {
 try {
 if (con != null)
 con.close();
 LogUtil.warn("------------------------------>Connection Closed","<---");
 } catch (SQLException e) {
 LogUtil.error("Error closing connection: ", e,"----");
 }
 }
}
//-------------------------------------------------------------------------------------------------------


// Close connection
connection.disconnect();
} catch (Exception e) {
e.printStackTrace();
}"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.util.ArrayList;
import java.util.Collection;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import java.lang.String;
import org.joget.workflow.model.service.*;
import java.lang.Exception;
import org.joget.commons.util.LogUtil;
 
import org.joget.apps.app.model.AppDefinition;
import org.joget.apps.app.service.AppService;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import org.joget.workflow.model.WorkflowAssignment;


import org.joget.workflow.model.service.*;


 
 
 
 //Get record Id from process
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
String recordid = appService.getOriginProcessId(workflowAssignment.getProcessId());
LogUtil.warn("record id",recordid);

// Database connection
Connection con = null;

// Get enquete ID
String id_enquete="#form.pmt.id_enquete#";
String enquete =recordid;
String identmen = "#form.pmt.identmen#";
String npi_inexistant = "#form.pmt.npi_inexistant#";
LogUtil.info("---enquete id ------", enquete);
LogUtil.info("---menage id ------", identmen);
LogUtil.info("---npi_inexistant id ------", npi_inexistant);


// Collection to store NPIs of selected members
Collection membres = new ArrayList();

try {
 // Get DataSource and Connection
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 String npi="";
 String count_menage="";
 
 // First query to select NPIs of members in the survey
 String selectQuery = "SELECT c_numero_npi FROM app_fd_table_individus WHERE c_id_enquete = ?";
 PreparedStatement selectPstmt = con.prepareStatement(selectQuery);
 selectPstmt.setString(1, enquete);
 ResultSet rs = selectPstmt.executeQuery();
 LogUtil.warn("completed executing select query","!!!!!!!!!!");
 // Store NPIs in the collection
 while (rs.next()) {
 npi = rs.getString("c_numero_npi");
 LogUtil.info("npi------------>", npi);
 membres.add(npi);
 }
 LogUtil.warn("completed treating rs","-!!!!!!!");
 rs.close();
 selectPstmt.close();
 membres.add(npi_inexistant);
 //select inexistant count 
 String selectQuery2 = "SELECT c_menage_inexistant_counter FROM app_fd_d_preinscription WHERE c_npi = ?";
 PreparedStatement selectPstmt2 = con.prepareStatement(selectQuery2);
 selectPstmt2.setString(1, npi_inexistant);
 ResultSet rs2 = selectPstmt2.executeQuery();
 while (rs2.next()) {
 count_menage = rs2.getString("c_menage_inexistant_counter");
 LogUtil.info("menage inexistant------------>", count_menage);
 }
 LogUtil.warn("completed treating rs2","-!!!!!!!");
 rs2.close();
 selectPstmt2.close();
 // Update query for the demandes in app_fd_d_preinscription based on selected NPIs
 int count_abs=Integer.parseInt(count_menage);
 // count_menage.isEmpty() || count_menage.isNull()? 0 : Integer.parseInt(count_menage);
 // if (count_menage != null && !count_menage.isEmpty()) {
 // count_abs = Integer.parseInt(count_menage);
 // }
 
 
 String updateQuery = "UPDATE app_fd_d_preinscription SET c_statut_demande = ?, c_id_enquete = ?, c_identmen = ?, c_menage_inexistant_counter=? WHERE c_npi = ?";
 String updateQueryEnquete="UPDATE app_fd_pmt set c_statut_enquete=? where c_npi_inexistant=?";
 PreparedStatement updatePstmt = con.prepareStatement(updateQuery);
 PreparedStatement updatePstmtEnquete = con.prepareStatement(updateQueryEnquete);
 String status="";
 if(count_abs==2){
 status="Demande clôturée";
 }else{
 status="A réenquêter";
 }
 LogUtil.warn("menage status------------>", status);
 // Loop through each member and execute the update
 // ++count_abs;
 int count_abs2=count_abs+1;

 String counter_abs_s=count_abs2.toString();
 LogUtil.warn("menage cpunter-------------------------------------------------------->", counter_abs_s);
 for (String npi : membres) {
 // Set parameters for the update (replace "new_status", "new_id_enquete", "new_id_menage" with actual values)
 updatePstmt.setString(1, status); // Update with desired status
 updatePstmt.setString(2, id_enquete); // Update enquete ID
 updatePstmt.setString(3, identmen); // Update with desired id_menage
 updatePstmt.setString(4,counter_abs_s); // Where clause based on NPI
 updatePstmt.setString(5, npi_inexistant); // Where clause based on NPI
 // Execute update
 int rowsUpdated = updatePstmt.executeUpdate();
 LogUtil.info("Updated rows for NPI " + npi + ": ", String.valueOf(rowsUpdated));
 }
 updatePstmtEnquete.setString(1,status);
 updatePstmtEnquete.setString(2,npi_inexistant);
 
 updatePstmt.close();
 LogUtil.info("Updates completed successfully.", "");

} catch (SQLException e) {
 LogUtil.error("Beanshell", e, "SQL Exception occurred.");
} finally {
 // Close the resources
 try {
 if (con != null) con.close();
 } catch (SQLException e) {
 LogUtil.error("Beanshell", e, "Error closing resources.");
 }
}
"}}]}

