{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import org.joget.directory.model.service.DirectoryManager;
import org.joget.directory.model.User;
import org.joget.commons.util.LogUtil;
import java.util.*;
import org.joget.apps.app.service.AppUtil;
// Input: Define your filter criteria
// evaluation_users
import org.joget.workflow.model.service.*;
import java.lang.Exception;
import org.joget.commons.util.LogUtil;
import org.joget.apps.app.model.AppDefinition;
import org.joget.apps.app.service.AppService;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import org.joget.workflow.model.WorkflowAssignment;
import org.joget.workflow.model.service.*;


String departmentId = "cellule"; // Replace with your department ID
String departmentIdanps = "anps"; // Replace with your department ID
String gradeId = "responsable"; // Replace with your role ID

// Output: Store matched users
Collection matchedUsers = new ArrayList();

try {
 String usernames="";
 // Get the DirectoryManager instance
 DirectoryManager directoryManager = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");

 // Retrieve users based on filters
 Collection users = directoryManager.getUsers(null, "rsu", departmentId, gradeId, null, null, "1", null, false, null, null);
 Collection users2= directoryManager.getUsers(null, "rsu", departmentIdanps, gradeId, null, null, "1", null, false, null, null);
 // Iterate through users and collect usernames
 for (Object obj : users) {
 User user = (User) obj;
 matchedUsers.add(user.getUsername());
 }
 for (Object obj : users2) {
 User user = (User) obj;
 usernames=usernames+user.getUsername();
 matchedUsers.add(user.getUsername());
 }

 
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
String recordid = appService.getOriginProcessId(workflowAssignment.getProcessId());
LogUtil.warn("record id",recordid);
WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
// wm.activityVariable(workflowAssignment.getActivityId(),"processID", recordid);
wm.activityVariable(workflowAssignment.getActivityId(),"evaluation_users", usernames);


// return matchedUsers;
 // Log the matched users
 LogUtil.info("ProcessMapping", "Matched Users: " + matchedUsers);

} catch (Exception e) {
 LogUtil.error("ProcessMapping", e, e.getMessage());
}
"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import org.joget.apps.app.service.AppUtil; 
