PreparedStatement stmt2 = con.prepareStatement("select pmt.id, concat(ind.c_hl2a,' ',ind.c_hl2b) as fullname, concat(dep.c_libelle,',',arr.c_libelle,',',comm.c_libelle) as adress, pmt.c_categorie as categorie, pmt.c_categorie_commission as categorieCommission from app_fd_pmt pmt right join app_fd_dossier_commission com on (com.c_id_dossier=pmt.id) left join app_fd_table_individus ind on (ind.c_id_enquete=pmt.id) left join app_fd_table_menages tm on (tm.c_id_parent=pmt.id) left join app_fd_department dep on( dep.id=tm.c_hh1 ) left join app_fd_arrondissement arr on (arr.id=tm.c_hh3) left join app_fd_commune comm on (comm.id=tm.c_hh2) where com.c_id_commission=?");
stmt2.setString(1, recordid);
rs = stmt2.executeQuery();
JSONArray DecisionArray = new JSONArray();
while (rs.next()) {
 countDossier++;
 JSONObject decision = new JSONObject();
 String catComm=rs.getString("categorieCommission");
 decision.put("num",countDossier);
 decision.put("name",rs.getString("fullname"));
 decision.put("adress",rs.getString("adress"));
 decision.put("cat",rs.getString("categorie"));
 decision.put("catcomm",catComm);
 if(catComm == null || catComm.isEmpty()){
 
 }else{
 countSubmitted++;
 if(catComm.equals("Pauvre")){
 countPauvre++;
 }else if(catComm.equals("Extrément pauvre")){
 countPauvreExtreme++;
 }else if(catComm.equals("Non pauvre")){
 countNNpauvre++;
 }else if(catComm.equals("Non reconnu")){
 countNNreconnus++;
 }
 }
 DecisionArray.put(decision);
 }
data.put("listDemande", DecisionArray);
data.put("count_dossier",countDossier);
data.put("submitted",countSubmitted);
data.put("pauv_extr",countPauvreExtreme);
data.put("nn_pauv",countNNpauvre);
data.put("pauv",countPauvre);
data.put("nn_recon",countNNreconnus);
LogUtil.info("------------data------------->", data.toString());
jsonData.put("data", data);
jsonData.put("output_path", output_path+"/commission/"+recordid);
jsonData.put("output_file_name", output_file_name);
LogUtil.info("---------------------------->6", jsonData.toString());
//UPDATE FILE COMMISSON
// commissionFileDocRecordID---Commission
String UpdateFile = "update app_fd_commission set c_pv_commission=? where id=? ;";
stmtUpdateFileName = con.prepareStatement(UpdateFile);
stmtUpdateFileName.setString(1, output_file_name2);
stmtUpdateFileName.setString(2, recordid);

stmtUpdateFileName.executeUpdate();
//UPDATE FILE COMMISSON


HitApi(lien,jsonData);

 rs.close();
 stmt.close();
 con.close();
} catch (SQLException e) {
 LogUtil.error("RSU", e, "Error executing SQL query");
} catch (Exception ex) {
 LogUtil.error("RSU", ex, "Error in script generation pv commission");
}"}}]}

