 LogUtil.warn("pmt FOUD-----------------------------------",pmt.toString());
 if (pmt.isEmpty()) {
 LogUtil.warn("error Aucun pmtne retrieved","");
 } else{
 for (Object obj : pmt) {
 if (obj instanceof FormRow) {
 String num_menage=getMenage(idPMT);
 Random random = new Random();
 int randomNumber = random.nextInt(100) + 1; 
 int score=randomNumber;
 int result = Integer.parseInt(num_menage);
 String category=getPovertyCategory(result,score);
 obj.put("score",score);
 obj.put("categorie",category);
 FormRowSet rowSet = new FormRowSet();
 rowSet.add(obj);
 LogUtil.warn("final obj -----------------------------------",obj.toString());
 try{
 String recordID ="#form.pmt.id#";
 Connection con = null;
 try {
 Connection con = null;
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 String updateQuery = "UPDATE app_fd_pmt SET c_score = ?, c_categorie = ? WHERE id = ?";
 PreparedStatement updateStatement = con.prepareStatement(updateQuery);
 updateStatement.setString(1,score.toString());
 updateStatement.setString(2,category.toString());
 updateStatement.setString(3,recordID);
 updateStatement.executeUpdate();
 } catch (SQLException e) {
 LogUtil.error("Beanshell", e, "SQL Exception occurred during insert.");
 } finally {
 // Close the resources
 try {
 if(con!=null)
 con.close();
 } catch (SQLException e) {
 LogUtil.error("Beanshell", e, "Error closing resources.");
 }
 }
 
 }catch(Exception x){

 }
 // dao.saveOrUpdate("enquete_pmt_id","pmt",rowSet);
 }
 }
 }
}

