 return presents >=result;
}*/

public boolean MinimumRequiredMembresAvailable(int minimumNumber, int presents){
 return presents >= minimumNumber;
}

int membresPresents=0;

Connection con = null;
try {
 // retrieve connection from the default datasource
 DataSource ds = (DataSource)AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 // execute SQL query
 if(!con.isClosed()) {
 PreparedStatement stmtSelectMembresPresents = con.prepareStatement("select count(*) from app_fd_membre_commission where c_id_commission=? and c_Presence='Présent';");
 stmtSelectMembresPresents.setString(1,"#variable.processID#");
 ResultSet rs2 = stmtSelectMembresPresents.executeQuery();
 while (rs2.next()) {
 LogUtil.info(" --------------------> membres de la commission présents (count) -----------> ",String.valueOf(rs2.getString(1)));
 try {
 membresPresents = Integer.parseInt(rs2.getString(1));
 }catch(Exception e){
 Logutil.error("-------- Error parsing count -------->",e,"Error parsing");
 }
 }
 
 }
 
} catch(Exception e) {
 LogUtil.error("error getting members commission ", e, "error SQL");
} finally {
 try {
 if(con != null) {
 con.close();
 }
 } catch(SQLException e) {/* ignored */}
}



 
if(!MinimumRequiredMembresAvailable(MINIMUM_MEMBRES_REQUIRED, membresPresents)){
 WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(),"quorum", "false");
 LogUtil.info(" --------------------> quorom -----------> ","false");
}else{
 WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
