{"script":"import java.util.ArrayList;
import java.util.Collection;
import org.joget.apps.app.service.AppUtil;
import org.joget.directory.model.User;
import org.joget.directory.model.service.ExtDirectoryManager;
import org.joget.workflow.model.WorkflowActivity;
import org.joget.commons.util.LogUtil;

 
public Collection getAssignees(WorkflowActivity activity) {
 Collection assignees = new ArrayList();
 ExtDirectoryManager directoryManager = (ExtDirectoryManager) pluginManager.getBean("directoryManager");
 //Get users using directory manager
 String assigneesIds= "#variable.assignees#";
 String[] idArray = assigneesIds.split(";");
 for (String id : idArray) {
 if (!id.trim().isEmpty()) {
 LogUtil.info("Individual ID", id);
 assignees.add(id);
 }
 }
 return assignees;
}
//call getAssignees method with injected variable
return getAssignees(workflowActivity);"}

{"script":"import org.joget.directory.model.service.DirectoryManager;
import org.joget.directory.model.User;
import org.joget.commons.util.LogUtil;
import java.util.*;
import org.joget.apps.app.service.AppUtil;
// Input: Define your filter criteria
// evaluation_users


String departmentId = "anps"; // Replace with your department ID
String gradeId = "responsable"; // Replace with your role ID

// Output: Store matched users
Collection matchedUsers = new ArrayList();

try {
 // Get the DirectoryManager instance
 DirectoryManager directoryManager = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");

 // Retrieve users based on filters
 Collection users = directoryManager.getUsers(null, "rsu", departmentId, gradeId, null, null, "1", null, false, null, null);
 // Iterate through users and collect usernames
 for (Object obj : users) {
 User user = (User) obj;
 matchedUsers.add(user.getUsername());
 }
return matchedUsers;
 // Log the matched users
 LogUtil.info("ProcessMapping", "Matched Users: " + matchedUsers);

} catch (Exception e) {
 LogUtil.error("ProcessMapping", e, e.getMessage());
}
"}

